﻿<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Request Blocked by WAF</title>

  <style>
    :root {
      --bg: #f6f8fb;
      --card: #ffffff;
      --text: #0b1f33;
      --muted: #54677a;
      --border: rgba(11,31,51,.12);
      --danger: #d32f2f;
      --danger-bg: rgba(211,47,47,.08);
      --info: #0288d1;
      --info-bg: rgba(2,136,209,.08);
      --radius: 18px;
    }

    * { box-sizing: border-box; }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
      background: var(--bg);
      color: var(--text);
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 24px;
    }

    .card {
      width: 100%;
      max-width: 720px;
      background: var(--card);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      padding: 32px;
      text-align: center;
    }

    .logo {
      margin-bottom: 20px;
    }

    .logo img {
      height: 48px;
      width: auto;
    }

    .badge {
      display: inline-block;
      padding: 6px 12px;
      border-radius: 999px;
      font-size: 12px;
      font-weight: 600;
      color: var(--danger);
      background: var(--danger-bg);
      margin-bottom: 16px;
    }

    h1 {
      margin: 0 0 12px;
      font-size: 26px;
      letter-spacing: -0.3px;
    }

    p {
      margin: 0 0 10px;
      color: var(--muted);
      line-height: 1.5;
    }

    .waf-details {
      margin: 20px 0;
      padding: 16px;
      border-radius: 12px;
      border: 1px solid var(--border);
      background: rgba(211,47,47,.04);
      text-align: left;
    }

    .waf-details h3 {
      margin: 0 0 12px;
      font-size: 15px;
      color: var(--danger);
    }

    .waf-details .waf-info {
      display: grid;
      gap: 10px;
      font-size: 13px;
    }

    .waf-details .waf-row {
      display: flex;
      align-items: baseline;
    }

    .waf-details .waf-label {
      font-weight: 600;
      color: var(--text);
      min-width: 120px;
    }

    .waf-details .waf-value {
      font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
      color: var(--muted);
      word-break: break-all;
    }

    .waf-reason {
      margin: 12px 0;
      padding: 12px;
      background: rgba(211,47,47,.1);
      border-left: 3px solid var(--danger);
      border-radius: 4px;
      font-size: 13px;
      text-align: left;
      font-weight: 500;
      color: var(--text);
    }

    .info-box {
      margin: 20px 0;
      padding: 16px;
      border-radius: 12px;
      border: 1px solid rgba(2,136,209,.2);
      background: var(--info-bg);
      text-align: left;
    }

    .info-box h3 {
      margin: 0 0 12px;
      font-size: 15px;
      color: var(--info);
    }

    .info-box ul {
      margin: 8px 0;
      padding-left: 20px;
    }

    .info-box li {
      margin: 6px 0;
      color: var(--text);
      line-height: 1.5;
    }

    .info-box .critical-step {
      margin: 10px 0 12px;
      padding: 10px 12px;
      border-left: 4px solid var(--danger);
      background: rgba(211,47,47,.08);
      border-radius: 6px;
      font-weight: 700;
    }

    .actions {
      margin-top: 24px;
      display: flex;
      gap: 12px;
      justify-content: center;
      flex-wrap: wrap;
    }

    .btn {
      padding: 12px 24px;
      border-radius: 12px;
      border: 1px solid var(--text);
      background: var(--text);
      color: var(--card);
      font-weight: 600;
      font-size: 14px;
      text-decoration: none;
      cursor: pointer;
      transition: all 0.2s ease;
      display: inline-block;
    }

    .btn:hover {
      background: transparent;
      color: var(--text);
      transform: translateY(-1px);
      box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
    }

    .support-hint {
      font-size: 13px;
      color: var(--muted);
      margin-top: 16px;
      line-height: 1.6;
    }

    .support-hint strong {
      color: var(--text);
    }

    footer {
      margin-top: 24px;
      font-size: 12px;
      color: var(--muted);
    }

    .tech-details {
      margin-top: 20px;
      padding: 12px;
      background: rgba(84,103,122,.04);
      border-radius: 8px;
      font-size: 11px;
      color: var(--muted);
      font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
      line-height: 1.6;
    }

    .tech-details div {
      margin: 4px 0;
    }

    .tech-details strong {
      color: var(--text);
      font-weight: 600;
    }

    /* Hide Cloudflare's default error box */
    #cf-error-details,
    div[class*="cf-error"],
    section[class*="cf-error"] {
      display: none !important;
    }
  </style>

  <script>
    // Extract WAF block information from URL parameters
    document.addEventListener('DOMContentLoaded', function() {
      const urlParams = new URLSearchParams(window.location.search);

      // Helper function to check if value is a Cloudflare template (not substituted)
      function isTemplate(value) {
        return !value || value.includes('{{') || value.includes('%7B%7B');
      }

      // Get the actual blocked URL
      // Use window.location.href which contains the full URL that was blocked by WAF
      // Remove the error page's own query parameters if Cloudflare appended them
      let requestUrl = window.location.href;

      // Clean up Cloudflare's error page parameters (ray_id, etc.) if present
      // Only use URL parameter override for 'original_url' or 'request_url' (not 'url' which could be a query param)
      const originalUrl = urlParams.get('original_url') || urlParams.get('request_url');
      if (originalUrl && !isTemplate(originalUrl)) {
        requestUrl = originalUrl;
      }

      // Remove common error page parameters from display URL to show the clean blocked URL
      requestUrl = requestUrl.split('?ray_id=')[0].split('&ray_id=')[0];

      // Get WAF block details
      const ruleId = urlParams.get('rule_id') || urlParams.get('rule') || 'Unknown';
      const timestamp = urlParams.get('timestamp') || new Date().toISOString();

      // Get Cloudflare Ray ID and Client IP from Cloudflare template variables or URL parameters
      // Cloudflare will replace a3e78baeddc3a305 and 103.86.54.118 when serving the error page
      let rayId = 'a3e78baeddc3a305';
      let clientIp = '103.86.54.118';

      // Check if Cloudflare has replaced the template variables (they won't contain :: anymore)
      if (rayId.includes('::')) {
        // Template not replaced, try URL parameters as fallback
        rayId = urlParams.get('ray_id') || urlParams.get('rayid') || 'Not available';
      }

      if (clientIp.includes('::')) {
        // Template not replaced, try URL parameters as fallback
        clientIp = urlParams.get('client_ip') || urlParams.get('ip') || 'Not available';
      }

      // Update the WAF block details
      document.getElementById('waf-url').textContent = requestUrl;
      document.getElementById('waf-timestamp').textContent = new Date(timestamp).toLocaleString();

      // Display Ray ID and Client IP on the page
      document.getElementById('error-ray-id').textContent = rayId;
      document.getElementById('error-client-ip').textContent = clientIp;

      // Build email body with WAF block details
      const emailSubject = 'WAF Block - Access Request';

      // Build email body line by line
      let emailBodyLines = [];
      emailBodyLines.push('Hello Support Team,');
      emailBodyLines.push('');
      emailBodyLines.push('My request was blocked by the security system.');
      emailBodyLines.push('');
      emailBodyLines.push('Block Details:');
      emailBodyLines.push('- Request URL: ' + requestUrl);
      emailBodyLines.push('- Blocked At: ' + new Date(timestamp).toLocaleString());
      emailBodyLines.push('- Cloudflare Ray ID: ' + rayId);
      emailBodyLines.push('- Client IP: ' + clientIp);
      emailBodyLines.push('');
      emailBodyLines.push('I believe this block was made in error. Please review and allow my access if appropriate.');
      emailBodyLines.push('');
      emailBodyLines.push('Thank you');

      const emailBody = emailBodyLines.join('\n');

      // Update the contact button with dynamic email
      const contactBtn = document.getElementById('contact-btn');
      if (contactBtn) {
        const mailtoLink = 'mailto:lbsupport@worldbankgroup.org' +
          '?subject=' + encodeURIComponent(emailSubject) +
          '&body=' + encodeURIComponent(emailBody);
        contactBtn.href = mailtoLink;
        console.log('Email link updated:', mailtoLink);
      } else {
        console.error('Contact button not found!');
      }

      // Hide the Cloudflare error box if it hasn't been replaced (still shows the token)
      const errorBox = document.getElementById('cloudflare-error-box');
      if (errorBox && errorBox.textContent.includes('::CLOUDFLARE_ERROR_1000S_BOX::')) {
        errorBox.style.display = 'none';
      }
    });
  </script>
</head>

<body>
  <main class="card" role="main">
    <div class="logo">
      <img src="data:image/svg+xml;base64," alt="World Bank Group logo">
    </div>

    <div class="badge">🛡️ WAF Block</div>

    <h1>Request Blocked by Security</h1>

    <p>
      Your request was blocked by our security system to protect against potential threats.
    </p>

    <div class="waf-details">
      <h3>Block Details:</h3>
      <div class="waf-reason">
        Your request was automatically blocked because it matched a pattern we use to protect against security threats.
      </div>
      <div class="waf-info">
        <div class="waf-row">
          <span class="waf-label">Request URL:</span>
          <span class="waf-value" id="waf-url">Loading...</span>
        </div>
        <div class="waf-row">
          <span class="waf-label">Blocked At:</span>
          <span class="waf-value" id="waf-timestamp">Loading...</span>
        </div>
      </div>
      <div class="tech-details">
        <div><strong>Cloudflare Ray ID:</strong> <span id="error-ray-id">Loading...</span></div>
        <div><strong>Client IP:</strong> <span id="error-client-ip">Loading...</span></div>
      </div>
    </div>

    <div class="info-box">
      <h3>What should you do next?</h3>
      <ul>
        <li class="critical-step">Clear your browser cache and cookies for this site</li>
        <li>Try accessing the page again</li>
        <li>If the issue persists, please report this issue using the button below</li>
      </ul>
    </div>

    <div class="actions">
      <a
        id="contact-btn"
        class="btn"
        href="mailto:lbsupport@worldbankgroup.org?subject=WAF%20Block%20-%20Access%20Request&body=Hello%20Support%20Team%2C%0A%0AMy%20request%20was%20blocked%20by%20the%20security%20system.%0A%0APlease%20assist.%0A%0AThank%20you">
        📧 Report Issue
      </a>
    </div>

    <p class="support-hint">
      Email: lbsupport@worldbankgroup.org
    </p>

    <div id="cloudflare-error-box" style="display: none;">
    ::CLOUDFLARE_ERROR_1000S_BOX::
    </div>

    <footer>
      © The World Bank Group
    </footer>
  </main>
</body>
</html>
